 12	public class MessageService {
 13	    private final List<Message> messages;
 14	    private final AtomicLong messageIdCounter;
 15	    private final boolean testMode;
 16	    private final String archiveEmail;
 17	
 18	    public MessageService() {
 19	        this.messages = new ArrayList<>();
 20	        this.messageIdCounter = new AtomicLong(0);
 21	        this.testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 22	        this.archiveEmail = "arquivo@pousadamarealta.com.br";
 23	    }
 24	
 25	    public void sendEmail(String to, String subject, String body) {
 26	        if (!EmailValidator.isValid(to)) {
 27	            addMessage(MessageChannel.EMAIL, to, subject, body, MessageStatus.BLOCKED);
 28	            return;
 29	        }
 30	
 31	        if (testMode) {
 32	            String originalTo = to;
 33	            String testTo = "testes@pousadamarealta.com.br";
 34	            String testSubject = "[TESTE] " + subject;
 35	            String testBody = "Destinatário original: " + originalTo + "\n" + body;
 36	
 37	            addMessage(MessageChannel.EMAIL, testTo, testSubject, testBody, MessageStatus.SENT);
 38	        } else {
 39	            addMessage(MessageChannel.EMAIL, to, subject, body, MessageStatus.SENT);
 40	
 41	            String archiveSubject = "[Cópia] " + subject;
 42	            addMessage(MessageChannel.EMAIL, archiveEmail, archiveSubject, body, MessageStatus.SENT);
 43	        }
 44	    }
 45	
 46	    private void addMessage(MessageChannel channel, String to, String subject, String body, MessageStatus status) {
 47	        long messageId = messageIdCounter.incrementAndGet();
 48	        Message message = new Message(messageId, channel, to, subject, body, status);
 49	        messages.add(message);
 50	    }
 51	
 52	    public List<Message> getAllMessages() {
 53	        return Collections.unmodifiableList(messages);
 54	    }
 55	}
 56	package com.pousadamarealta.util;
 57	
 58	public class EmailValidator {
 59	    public static boolean isValid(String email) {
 60	        if (email == null || email.isEmpty()) {
 61	            return false;
 62	        }
 63	
 64	        int atIndex = email.indexOf('@');
 65	        if (atIndex <= 0 || email.indexOf('@', atIndex + 1) != -1) {
 66	            return false;
 67	        }
 68	
 69	        String domain = email.substring(atIndex + 1);
 70	        return domain.contains(".");
 71	    }
 72	}
