   18	
   19	public class ReservationService {
   20	    private final List<Reservation> reservations;
   21	    private final AtomicLong reservationIdCounter;
   22	    private final RoomService roomService;
   23	    private final MessageService messageService;
   24	
   25	    public ReservationService(RoomService roomService, MessageService messageService) {
   26	        this.reservations = new ArrayList<>();
   27	        this.reservationIdCounter = new AtomicLong(0);
   28	        this.roomService = roomService;
   29	        this.messageService = messageService;
   30	    }
   31	
   32	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
   33	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
   34	        Optional<Room> room = roomService.getRoomByNumber(roomNumber);
   35	        if (room.isEmpty()) {
   36	            throw new IllegalArgumentException("Room not found");
   37	        }
   38	
   39	        Room r = room.get();
   40	
   41	        if (guests < 1 || guests > r.getCapacity()) {
   42	            throw new IllegalArgumentException("Invalid guest count");
   43	        }
   44	
   45	        if (!checkOut.isAfter(checkIn)) {
   46	            throw new IllegalArgumentException("Check-out must be after check-in");
   47	        }
   48	
   49	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
   50	            throw new IllegalArgumentException("Room unavailable for those dates");
   51	        }
   52	
   53	        PriceCalculator.PriceBreakdown prices = PriceCalculator.calculate(r.getNightlyRate(), checkIn, checkOut, ratePlan);
   54	
   55	        long resId = reservationIdCounter.incrementAndGet();
   56	        Reservation reservation = new Reservation(
   57	                resId, roomNumber, guestName, guestEmail, guestCpf,
   58	                checkIn, checkOut, guests, ratePlan,
   59	                prices.nights, prices.subtotal, prices.discount, prices.total
   60	        );
   61	
   62	        reservations.add(reservation);
   63	        return reservation;
   64	    }
   65	
   66	    public Optional<Reservation> getReservation(long id) {
   67	        return reservations.stream()
   68	                .filter(r -> r.getId() == id)
   69	                .findFirst();
   70	    }
   71	
   72	    public Reservation confirmReservation(long id, BigDecimal amountPaid) {
   73	        Optional<Reservation> opt = getReservation(id);
   74	        if (opt.isEmpty()) {
   75	            throw new IllegalArgumentException("Reservation not found");
   76	        }
   77	
   78	        Reservation reservation = opt.get();
   79	
   80	        if (reservation.getStatus() != ReservationStatus.PENDING) {
   81	            throw new IllegalArgumentException("Cannot confirm a non-pending reservation");
   82	        }
   83	
   84	        reservation.setStatus(ReservationStatus.CONFIRMED);
   85	        reservation.setAmountPaid(amountPaid);
   86	
   87	        Optional<Room> room = roomService.getRoomByNumber(reservation.getRoomNumber());
   88	        if (room.isPresent()) {
   89	            Receipt receipt = buildReceipt(reservation, room.get());
   90	            String receiptText = formatReceipt(receipt);
   91	            String emailBody = buildConfirmationEmail(reservation.getGuestName(), receiptText);
   92	            messageService.sendEmail(reservation.getGuestEmail(), "Reserva confirmada - Pousada Maré Alta", emailBody);
   93	        }
   94	
   95	        return reservation;
   96	    }
   97	
   98	    public Reservation checkIn(long id) {
   99	        Optional<Reservation> opt = getReservation(id);
  100	        if (opt.isEmpty()) {
  101	            throw new IllegalArgumentException("Reservation not found");
  102	        }
  103	
  104	        Reservation reservation = opt.get();
  105	
  106	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
  107	            throw new IllegalArgumentException("Cannot check-in a non-confirmed reservation");
  108	        }
  109	
  110	        reservation.setStatus(ReservationStatus.CHECKED_IN);
  111	        return reservation;
  112	    }
  113	
  114	    public Receipt checkOut(long id) {
  115	        Optional<Reservation> opt = getReservation(id);
  116	        if (opt.isEmpty()) {
  117	            throw new IllegalArgumentException("Reservation not found");
  118	        }
  119	
  120	        Reservation reservation = opt.get();
  121	
  122	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
  123	            throw new IllegalArgumentException("Cannot check-out without prior check-in");
  124	        }
  125	
  126	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
  127	
  128	        Optional<Room> room = roomService.getRoomByNumber(reservation.getRoomNumber());
  129	        if (room.isEmpty()) {
  130	            throw new IllegalArgumentException("Room not found");
  131	        }
  132	
  133	        return buildReceipt(reservation, room.get());
  134	    }
  135	
  136	    public Reservation cancelReservation(long id) {
  137	        Optional<Reservation> opt = getReservation(id);
  138	        if (opt.isEmpty()) {
  139	            throw new IllegalArgumentException("Reservation not found");
  140	        }
  141	
  142	        Reservation reservation = opt.get();
  143	
  144	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
  145	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
  146	            reservation.getStatus() == ReservationStatus.CANCELLED) {
  147	            throw new IllegalArgumentException("Cannot cancel a reservation at this status");
  148	        }
  149	
  150	        BigDecimal refund = BigDecimal.ZERO;
  151	        if (reservation.getStatus() == ReservationStatus.CONFIRMED) {
  152	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
  153	                refund = reservation.getAmountPaid();
  154	            }
  155	        }
  156	
  157	        reservation.setStatus(ReservationStatus.CANCELLED);
  158	        reservation.setRefund(MoneyUtil.round(refund));
  159	
  160	        return reservation;
  161	    }
  162	
  163	    public Receipt getReceipt(long id) {
  164	        Optional<Reservation> opt = getReservation(id);
  165	        if (opt.isEmpty()) {
  166	            throw new IllegalArgumentException("Reservation not found");
  167	        }
  168	
  169	        Reservation reservation = opt.get();
  170	
  171	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
  172	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
  173	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
  174	            throw new IllegalArgumentException("Receipt only available for paid reservations");
  175	        }
  176	
  177	        Optional<Room> room = roomService.getRoomByNumber(reservation.getRoomNumber());
  178	        if (room.isEmpty()) {
  179	            throw new IllegalArgumentException("Room not found");
  180	        }
  181	
  182	        return buildReceipt(reservation, room.get());
  183	    }
  184	
  185	    public List<Reservation> getReservationsByRoomAndDate(int roomNumber, LocalDate date) {
  186	        List<Reservation> result = new ArrayList<>();
  187	        for (Reservation r : reservations) {
  188	            if (r.getRoomNumber() == roomNumber &&
  189	                !r.getCheckIn().isAfter(date) &&
  190	                r.getCheckOut().isAfter(date) &&
  191	                r.getStatus() != ReservationStatus.CANCELLED) {
  192	                result.add(r);
  193	            }
  194	        }
  195	        return result;
  196	    }
  197	
  198	    public List<Reservation> getConfirmedReservationsByRoomAndDate(int roomNumber, LocalDate date) {
  199	        List<Reservation> result = new ArrayList<>();
  200	        for (Reservation r : reservations) {
  201	            if (r.getRoomNumber() == roomNumber &&
  202	                !r.getCheckIn().isAfter(date) &&
  203	                r.getCheckOut().isAfter(date) &&
  204	                (r.getStatus() == ReservationStatus.CONFIRMED ||
  205	                 r.getStatus() == ReservationStatus.CHECKED_IN ||
  206	                 r.getStatus() == ReservationStatus.CHECKED_OUT)) {
  207	                result.add(r);
  208	            }
  209	        }
  210	        return result;
  211	    }
  212	
  213	    public List<Reservation> getReservationsByMonthStarting(int year, int month) {
  214	        LocalDate monthStart = LocalDate.of(year, month, 1);
  215	        LocalDate monthEnd = monthStart.plusMonths(1);
  216	
  217	        List<Reservation> result = new ArrayList<>();
  218	        for (Reservation r : reservations) {
  219	            if (!r.getCheckIn().isBefore(monthStart) && r.getCheckIn().isBefore(monthEnd) &&
  220	                (r.getStatus() == ReservationStatus.CONFIRMED ||
  221	                 r.getStatus() == ReservationStatus.CHECKED_IN ||
  222	                 r.getStatus() == ReservationStatus.CHECKED_OUT ||
  223	                 r.getStatus() == ReservationStatus.CANCELLED && r.getRefund() != null)) {
  224	                result.add(r);
  225	            }
  226	        }
  227	        return result;
  228	    }
  229	
  230	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
  231	        LocalDate current = checkIn;
  232	        while (current.isBefore(checkOut)) {
  233	            if (!getReservationsByRoomAndDate(roomNumber, current).isEmpty()) {
  234	                return true;
  235	            }
  236	            current = current.plusDays(1);
  237	        }
  238	        return false;
  239	    }
  240	
  241	    private Receipt buildReceipt(Reservation reservation, Room room) {
  242	        return new Receipt(
  243	                reservation.getId(),
  244	                reservation.getGuestName(),
  245	                reservation.getGuestCpf(),
  246	                reservation.getRoomNumber(),
  247	                room.getType(),
  248	                reservation.getCheckIn(),
  249	                reservation.getCheckOut(),
  250	                reservation.getNights(),
  251	                reservation.getSubtotal(),
  252	                reservation.getDiscount(),
  253	                reservation.getTotal()
  254	        );
  255	    }
  256	
  257	    private String formatReceipt(Receipt receipt) {
  258	        StringBuilder sb = new StringBuilder();
  259	        sb.append("Comprovante de reserva nº ").append(receipt.getReservationId()).append("\n");
  260	        sb.append("Hóspede: ").append(receipt.getGuestName()).append(" (CPF ").append(formatCpf(receipt.getGuestCpf())).append(")\n");
  261	        sb.append("Quarto: ").append(receipt.getRoomNumber()).append(" (").append(receipt.getRoomType()).append(")\n");
  262	        sb.append("Entrada: ").append(formatDate(receipt.getCheckIn())).append(" | ");
  263	        sb.append("Saída: ").append(formatDate(receipt.getCheckOut())).append(" | ");
  264	        sb.append(receipt.getNights()).append(receipt.getNights() == 1 ? " diária\n" : " diárias\n");
  265	        sb.append("Diárias: ").append(formatMoney(receipt.getSubtotal())).append("\n");
  266	        if (receipt.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
  267	            sb.append("Desconto: ").append(formatMoney(receipt.getDiscount())).append("\n");
  268	        }
  269	        sb.append("Total: ").append(formatMoney(receipt.getTotal()));
  270	        return sb.toString();
  271	    }
