373	    public String generateOccupancyReport(LocalDate date) {
374	        StringBuilder csv = new StringBuilder();
375	        csv.append("room,type,reservation,check_in,check_out\n");
376	
377	        List<Room> rooms = roomService.getAllRooms().stream()
378	                .sorted(Comparator.comparingInt(Room::getNumber))
379	                .collect(Collectors.toList());
380	
381	        int occupiedCount = 0;
382	        for (Room room : rooms) {
383	            List<Reservation> reservations = reservationService.getConfirmedReservationsByRoomAndDate(room.getNumber(), date);
384	            if (!reservations.isEmpty()) {
385	                for (Reservation res : reservations) {
386	                    csv.append(room.getNumber()).append(",");
387	                    csv.append(room.getType()).append(",");
388	                    csv.append(res.getId()).append(",");
389	                    csv.append(formatDate(res.getCheckIn())).append(",");
390	                    csv.append(formatDate(res.getCheckOut())).append("\n");
391	                    occupiedCount++;
392	                }
393	            }
394	        }
395	
396	        csv.append("total,").append(occupiedCount).append("/").append(rooms.size());
397	        return csv.toString();
398	    }
399	
400	    public String generateRevenueReport(YearMonth month) {
401	        StringBuilder csv = new StringBuilder();
402	        csv.append("reservation,room,check_in,check_out,status,amount\n");
403	
404	        List<Reservation> reservations = reservationService.getReservationsByMonthStarting(month.getYear(), month.getMonthValue())
405	                .stream()
406	                .sorted(Comparator.comparing(Reservation::getCheckIn)
407	                        .thenComparingLong(Reservation::getId))
408	                .collect(Collectors.toList());
409	
410	        BigDecimal total = BigDecimal.ZERO;
411	        for (Reservation res : reservations) {
412	            BigDecimal amount = calculateRevenueAmount(res);
413	            if (amount.compareTo(BigDecimal.ZERO) > 0) {
414	                csv.append(res.getId()).append(",");
415	                csv.append(res.getRoomNumber()).append(",");
416	                csv.append(formatDate(res.getCheckIn())).append(",");
417	                csv.append(formatDate(res.getCheckOut())).append(",");
418	                csv.append(res.getStatus()).append(",");
419	                csv.append(formatMoneyForCsv(amount)).append("\n");
420	                total = total.add(amount);
421	            }
422	        }
423	
424	        csv.append("total,").append(formatMoneyForCsv(total));
425	        return csv.toString();
426	    }
427	
428	    private BigDecimal calculateRevenueAmount(Reservation res) {
429	        BigDecimal paid = res.getAmountPaid();
430	        BigDecimal refund = res.getRefund() != null ? res.getRefund() : BigDecimal.ZERO;
431	        return paid.subtract(refund);
432	    }
433	
434	    private String formatDate(LocalDate date) {
435	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
436	    }
437	
438	    private String formatMoneyForCsv(BigDecimal amount) {
439	        return amount.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
440	    }
