322	        map.put("nights", r.getNights());
323	        map.put("subtotal", roundToTwoDecimals(r.getSubtotal()));
324	        map.put("discount", roundToTwoDecimals(r.getDiscount()));
325	        map.put("total", roundToTwoDecimals(r.getTotal()));
326	        map.put("status", r.getStatus().toString());
327	        map.put("amountPaid", roundToTwoDecimals(r.getAmountPaid()));
328	        map.put("refund", r.getRefund() != null ? roundToTwoDecimals(r.getRefund()) : null);
329	        return map;
330	    }
