333	        java.util.HashMap<String, Object> map = new java.util.HashMap<>();
334	        map.put("title", "Comprovante de reserva");
335	        map.put("reservationId", r.getReservationId());
336	        map.put("guestName", r.getGuestName());
337	        map.put("guestCpf", r.getGuestCpf());
338	        map.put("roomNumber", r.getRoomNumber());
339	        map.put("roomType", r.getRoomType());
340	        map.put("checkIn", r.getCheckIn().toString());
341	        map.put("checkOut", r.getCheckOut().toString());
342	        map.put("nights", r.getNights());
343	        map.put("subtotal", roundToTwoDecimals(r.getSubtotal()));
344	        map.put("discount", roundToTwoDecimals(r.getDiscount()));
345	        map.put("total", roundToTwoDecimals(r.getTotal()));
346	        return map;
347	    }
348	
349	    private double roundToTwoDecimals(BigDecimal value) {
350	        return value.setScale(2, java.math.RoundingMode.HALF_EVEN).doubleValue();
351	    }
